cd /home/user/rork-app && GITURL=$(git config --global --list 2>/dev/null | grep 'ivx-holdings-platform.insteadof' | head -1 | sed 's/url\.//' | sed 's/\.insteadof=.*//') && TOKEN=$(echo "$GITURL" | sed 's|https://||' | sed 's/@.*//' | cut -d: -f2) && echo "=== Get workflow logs ===" && curl -s --max-time 15 "https://api.github.com/repos/ibb142/ivx-holdings-platform/actions/runs/31806654488/jobs" \
  -H "Accept: application/vnd.github+json" \
  -H "Authorization: Bearer $TOKEN" 2>&1 | node -e "
const d=require('fs').readFileSync('/dev/stdin','utf-8');
const j=JSON.parse(d);
if(j.jobs && j.jobs[0]){
  const job = j.jobs[0];
  console.log('Job ID:', job.id);
  console.log('Job URL:', job.url);
  // Find the failed step
  const failedStep = job.steps.find(s => s.conclusion === 'failure');
  if(failedStep) console.log('Failed step:', failedStep.name, '(number:', failedStep.number + ')');
}
" && echo "" && echo "=== Download logs ===" && curl -s -L --max-time 15 "https://api.github.com/repos/ibb142/ivx-holdings-platform/actions/jobs/$(curl -s --max-time 10 'https://api.github.com/repos/ibb142/ivx-holdings-platform/actions/runs/31806654488/jobs' -H 'Accept: application/vnd.github+json' -H "Authorization: Bearer $TOKEN" | node -e "const d=require('fs').readFileSync('/dev/stdin','utf-8');const j=JSON.parse(d);process.stdout.write(j.jobs[0].id.toString())")/logs" \
  -H "Accept: application/vnd.github+json" \
  -H "Authorization: Bearer $TOKEN" 2>&1 | tail -60

