    console.error('  OWNER: Verify IAM permissions or rotate the key.');
    console.error('═════════════════════════════════════════════');
    process.exit(1);
  }
  results.push({ key: f.key, status: 'fail', error: e?.message || 'Unknown' });
  fail++;
}

